using System.Collections;
using UnityEngine;

/// <summary>
/// 房间摄像机控制器 — 固定房间视角 + 房间切换平滑滑动。
/// 挂载在 MainCamera 上。
/// 
/// 行为:
/// - 在房间中: 摄像机固定在房间中心，orthographicSize = 根据房间大小自动计算
/// - 房间切换: 平滑滑动到新房间中心 (0.5s)
/// - 过渡期间通知 MapManager 锁定玩家输入
/// </summary>
[RequireComponent(typeof(Camera))]
public class RoomCameraController : MonoBehaviour
{
    [Header("过渡设置")]
    [Tooltip("房间切换过渡时长 (秒)")]
    public float transitionDuration = 0.5f;

    [Tooltip("过渡曲线")]
    public AnimationCurve transitionCurve = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);

    [Header("视角设置")]
    [Tooltip("摄像机 Orthographic Size 与房间高度的比例 (1.0 = 正好包住房间内高，1.2 = 含墙壁+门边距)")]
    public float sizeScale = 1.2f;

    [Tooltip("最小 Orthographic Size")]
    public float minOrthoSize = 5f;

    [Tooltip("最大 Orthographic Size")]
    public float maxOrthoSize = 25f;

    private Camera _cam;
    private Vector3 _targetPosition;
    private float _targetOrthoSize;
    private bool _isTransitioning;
    private Coroutine _transitionCoroutine;
    private RoomRoot _currentRoom;

    private void Awake()
    {
        _cam = GetComponent<Camera>();
        _targetPosition = transform.position;
        _targetOrthoSize = _cam.orthographicSize;
    }

    private void LateUpdate()
    {
        if (!_isTransitioning)
        {
            // 固定模式：直接锁定在目标位置
            transform.position = _targetPosition;
            _cam.orthographicSize = _targetOrthoSize;
        }
    }

    /// <summary>切换摄像机到目标房间</summary>
    /// <param name="room">目标房间</param>
    /// <param name="onComplete">过渡完成回调</param>
    public void MoveToRoom(RoomRoot room, System.Action onComplete = null)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z; // 保持 Z 轴

        // 计算合适的 Orthographic Size
        float targetSize = CalculateOrthoSize(room);

        if (transitionDuration <= 0f || _targetPosition == roomCenter)
        {
            // 瞬间切换
            _targetPosition = roomCenter;
            _targetOrthoSize = targetSize;
            onComplete?.Invoke();
            return;
        }

        // 平滑过渡
        if (_transitionCoroutine != null)
            StopCoroutine(_transitionCoroutine);
        _transitionCoroutine = StartCoroutine(TransitionRoutine(roomCenter, targetSize, onComplete));
    }

    /// <summary>根据房间大小计算合适的 Orthographic Size。</summary>
    /// <remarks>房间视觉范围 = roomSize + 四周墙壁(0.5×2=1)。取高宽中较严的方向，确保全覆盖。</remarks>
    private float CalculateOrthoSize(RoomRoot room)
    {
        // 含墙壁的完整视觉尺寸
        float visualW = room.roomSize.x + 1f;
        float visualH = room.roomSize.y + 1f;

        // Orthographic Size = half height → 纵向覆盖需要 visualH/2
        float sizeFromHeight = visualH * 0.5f * sizeScale;
        // 横向覆盖需要 visualW/2 / aspect
        float sizeFromWidth = visualW * 0.5f * sizeScale / _cam.aspect;
        float size = Mathf.Max(sizeFromHeight, sizeFromWidth);
        return Mathf.Clamp(size, minOrthoSize, maxOrthoSize);
    }

    /// <summary>平滑过渡协程</summary>
    private IEnumerator TransitionRoutine(Vector3 targetPos, float targetSize, System.Action onComplete)
    {
        _isTransitioning = true;

        Vector3 startPos = transform.position;
        float startSize = _cam.orthographicSize;

        float elapsed = 0f;

        while (elapsed < transitionDuration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / transitionDuration);
            float curveT = transitionCurve.Evaluate(t);

            transform.position = Vector3.Lerp(startPos, targetPos, curveT);
            _cam.orthographicSize = Mathf.Lerp(startSize, targetSize, curveT);

            yield return null;
        }

        // 最终值精确设置
        transform.position = targetPos;
        _cam.orthographicSize = targetSize;
        _targetPosition = targetPos;
        _targetOrthoSize = targetSize;

        _isTransitioning = false;
        onComplete?.Invoke();
    }

    /// <summary>立即跳转到房间 (无过渡)</summary>
    public void SnapToRoom(RoomRoot room)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z;

        transform.position = roomCenter;
        _targetPosition = roomCenter;
        _targetOrthoSize = CalculateOrthoSize(room);
        _cam.orthographicSize = _targetOrthoSize;
    }

    public RoomRoot CurrentRoom => _currentRoom;
    public bool IsTransitioning => _isTransitioning;
}

using UnityEngine;

/// <summary>
/// 技能 UI Controller —— 监听 PlayerSkillManager（Model），通知 SkillUIPanel（View）。
/// 本类是 Model ↔ View 的唯一耦合点。
/// </summary>
public class SkillUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private PlayerSkillManager _skillManager;

    [Header("View 引用")]
    [SerializeField] private SkillUIPanel _panel;

    private SkillViewData[] _previousData = System.Array.Empty<SkillViewData>();

    // ==================== 生命周期 ====================

    private void Start()
    {
        if (_skillManager == null)
        {
            Debug.LogError("SkillUIController: PlayerSkillManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("SkillUIController: SkillUIPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_skillManager.SlotCount);
        _previousData = new SkillViewData[_skillManager.SlotCount];

        // 订阅 Model 事件
        _skillManager.OnSkillCast += HandleSkillCast;
        _skillManager.OnSkillUpgraded += HandleSkillUpgraded;

        // 初始全量刷新
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void Update()
    {
        if (_skillManager == null) return;

        // 每帧同步冷却变化（冷却值通过 SkillInstance 的公开属性读取）
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void OnDestroy()
    {
        if (_skillManager != null)
        {
            _skillManager.OnSkillCast -= HandleSkillCast;
            _skillManager.OnSkillUpgraded -= HandleSkillUpgraded;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleSkillCast(int index, SkillData data) => SyncSlot(index);
    private void HandleSkillUpgraded(int index, int newLevel) => SyncSlot(index);

    // ==================== 核心同步 ====================

    private void SyncSlot(int index)
    {
        SkillInstance skill = _skillManager.GetSkill(index);
        SkillViewData data = BuildViewData(index, skill);

        if (!data.Equals(_previousData[index]))
        {
            _previousData[index] = data;
            _panel.RefreshSlot(index, data);
        }
    }

    private SkillViewData BuildViewData(int index, SkillInstance skill)
    {
        SkillViewData data = default;

        data.IsUnlocked = _skillManager.IsSlotUnlocked(index);
        data.IsEquipped = skill != null;
        data.ShowKeyLabel = true;

        // 快捷键标签
        KeyCode key = _skillManager.GetKeyCode(index);
        data.KeyLabel = KeyCodeToString(key);

        if (skill != null)
        {
            SkillData def = skill.Data;
            data.Icon = def.icon;
            data.Level = skill.Level;
            data.MaxLevel = skill.MaxLevel;
            data.IsCoolingDown = skill.IsCoolingDown;
            data.CooldownPercent = skill.CooldownPercent;
            data.CooldownRemaining = skill.CooldownRemaining;
        }

        return data;
    }

    private static string KeyCodeToString(KeyCode key)
    {
        // 提取字母/数字部分，去除 "Alpha" 前缀
        string s = key.ToString();
        if (s.StartsWith("Alpha"))
            return s.Substring(5);
        return s;
    }
}

using UnityEngine;

/// <summary>
/// 技能 UI 面板 —— 管理 SkillSlotView 的创建与刷新。
/// </summary>
public class SkillUIPanel : MonoBehaviour
{
    [Header("预制体与容器")]
    [SerializeField] private SkillSlotView _slotPrefab;
    [SerializeField] private Transform _container;

    private SkillSlotView[] _views = System.Array.Empty<SkillSlotView>();

    /// <summary>Controller 调用，按数量创建槽位 View</summary>
    public void Initialize(int slotCount)
    {
        // 清理旧子对象
        for (int i = _container.childCount - 1; i >= 0; i--)
            SafeDestroy(_container.GetChild(i).gameObject);

        _views = new SkillSlotView[slotCount];
        for (int i = 0; i < slotCount; i++)
        {
            SkillSlotView view = Instantiate(_slotPrefab, _container);
            view.name = $"SkillSlot_{i}";
            _views[i] = view;
        }
    }

    /// <summary>Controller 调用，刷新指定槽位</summary>
    public void RefreshSlot(int index, in SkillViewData data)
    {
        if (index < 0 || index >= _views.Length) return;
        _views[index]?.Refresh(data);
    }

    /// <summary>获取指定槽位 View（供 Controller 绑定按钮事件）</summary>
    public SkillSlotView GetSlotView(int index)
    {
        if (index < 0 || index >= _views.Length) return null;
        return _views[index];
    }

    private static void SafeDestroy(Object obj)
    {
        if (obj == null) return;
        if (Application.isPlaying)
            Destroy(obj);
        else
            DestroyImmediate(obj);
    }
}

