/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [SerializeField] private float shootCooldown = 0.2f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => shootCooldown;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        health -= damage;
        health = Mathf.Max(health, 0);

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shootCooldown = Mathf.Max(shootCooldown, 0f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 生成子弹
        GameObject bullet = Instantiate(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.F },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.R },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（留空则不装备）")]
    [SerializeField] private string _initialSkillId;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkill();
    }

    private void EquipInitialSkill()
    {
        if (string.IsNullOrEmpty(_initialSkillId)) return;
        EquipSkill(0, _initialSkillId);
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using System;
using UnityEngine;

/// <summary>
/// 传递给 SkillSlotView 的纯显示数据 DTO，无行为。
/// Controller 从 SkillInstance / SkillSlot 提取后传入 View。
/// </summary>
public struct SkillViewData : IEquatable<SkillViewData>
{
    public Sprite Icon;
    public string KeyLabel;
    public bool ShowKeyLabel;
    public int Level;
    public int MaxLevel;
    public bool IsEquipped;
    public bool IsUnlocked;
    public bool IsCoolingDown;
    public float CooldownPercent;
    public float CooldownRemaining;

    public bool Equals(SkillViewData other)
    {
        return ReferenceEquals(Icon, other.Icon)
            && KeyLabel == other.KeyLabel
            && Level == other.Level
            && MaxLevel == other.MaxLevel
            && IsEquipped == other.IsEquipped
            && IsUnlocked == other.IsUnlocked
            && IsCoolingDown == other.IsCoolingDown
            && ShowKeyLabel == other.ShowKeyLabel
            && Mathf.Approximately(CooldownPercent, other.CooldownPercent)
            && Mathf.Approximately(CooldownRemaining, other.CooldownRemaining);
    }

    public override bool Equals(object obj) => obj is SkillViewData other && Equals(other);

    public override int GetHashCode()
    {
        unchecked
        {
            int hash = 17;
            hash = hash * 23 + (Icon != null ? Icon.GetHashCode() : 0);
            hash = hash * 23 + (KeyLabel != null ? KeyLabel.GetHashCode() : 0);
            hash = hash * 23 + Level.GetHashCode();
            hash = hash * 23 + MaxLevel.GetHashCode();
            hash = hash * 23 + IsEquipped.GetHashCode();
            hash = hash * 23 + IsUnlocked.GetHashCode();
            hash = hash * 23 + IsCoolingDown.GetHashCode();
            hash = hash * 23 + CooldownPercent.GetHashCode();
            hash = hash * 23 + CooldownRemaining.GetHashCode();
            return hash;
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 技能槽位 View —— 纯渲染，不引用任何游戏逻辑。
/// 由 Controller 调用 Refresh() 更新显示。
/// </summary>
public class SkillSlotView : MonoBehaviour
{
    [Header("图标与文本")]
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _keyLabel;
    [SerializeField] private TMP_Text _levelText;

    [Header("冷却")]
    [SerializeField] private Image _cooldownOverlay;
    [SerializeField] private TMP_Text _cooldownText;

    [Header("状态遮罩")]
    [SerializeField] private GameObject _lockedOverlay;
    [SerializeField] private GameObject _emptyOverlay;

    [Header("交互")]
    [SerializeField] private Button _upgradeButton;

    /// <summary>Controller 调用，传入数据刷新 UI</summary>
    public void Refresh(in SkillViewData data)
    {
        // 图标
        if (_icon != null)
        {
            _icon.sprite = data.Icon;
            _icon.enabled = data.Icon != null;
        }

        // 快捷键
        if (_keyLabel != null)
        {
            _keyLabel.text = data.KeyLabel;
            _keyLabel.gameObject.SetActive(data.ShowKeyLabel);
        }

        // 等级
        if (_levelText != null)
            _levelText.text = data.IsEquipped ? $"Lv.{data.Level}" : "";

        // 冷却填充 — 仅在冷却中显示，否则完全隐藏
        if (_cooldownOverlay != null)
        {
            _cooldownOverlay.fillAmount = data.CooldownPercent;
            _cooldownOverlay.enabled = data.IsCoolingDown && data.CooldownPercent > 0f;
        }

        // 冷却数字
        if (_cooldownText != null)
        {
            bool showCooldown = data.IsCoolingDown && data.CooldownRemaining > 0f;
            _cooldownText.gameObject.SetActive(showCooldown);
            if (showCooldown)
                _cooldownText.text = $"{data.CooldownRemaining:F1}s";
        }

        // 解锁/空槽遮罩
        if (_lockedOverlay != null)
            _lockedOverlay.SetActive(!data.IsUnlocked);
        if (_emptyOverlay != null)
            _emptyOverlay.SetActive(data.IsUnlocked && !data.IsEquipped);

        // 升级按钮 — 未装备或满级时隐藏
        if (_upgradeButton != null)
            _upgradeButton.gameObject.SetActive(data.IsEquipped && data.Level < data.MaxLevel);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 侵蚀技能夺取弹窗 — 全局暂停时显示敌人技能列表，供玩家选择夺取/升级。
/// UI 结构由预制体预设；运行时只动态填充技能槽。
/// </summary>
public class SkillStealPopupManager : MonoBehaviour
{
    public static SkillStealPopupManager Instance { get; private set; }

    [Header("预制体")]
    [SerializeField] private SkillSlotView _slotPrefab;

    [Header("弹窗 UI（预制体中预设）")]
    [SerializeField] private GameObject _backdrop;
    [SerializeField] private GameObject _popupPanel;
    [SerializeField] private Transform _slotContainer;
    [SerializeField] private Text _titleText;
    [SerializeField] private Text _cancelText;
    [SerializeField] private Button _cancelButton;

    private Font _runtimeFont;
    private IReadOnlyList<SkillInstance> _enemySkills;
    private PlayerSkillManager _playerSkillManager;
    private Action _onClose;
    private bool _isShowing;

    private void Awake()
    {
        if (Instance == null)
            Instance = this;
        else
            Destroy(gameObject);

        // 动态字体无法被预制体序列化，运行时创建
        _runtimeFont = Font.CreateDynamicFontFromOSFont("Arial", 16);

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    private void OnDestroy()
    {
        // 切换场景时清理单例
        if (Instance == this)
            Instance = null;
    }

    public void ShowPopup(IReadOnlyList<SkillInstance> enemySkills, PlayerSkillManager player, Action onClose)
    {
        if (_isShowing) return;
        _isShowing = true;

        _enemySkills = enemySkills;
        _playerSkillManager = player;
        _onClose = onClose;

        if (_popupPanel == null) { _isShowing = false; return; }

        if (_titleText != null)
        {
            _titleText.font = _runtimeFont;
            _titleText.text = "选择要夺取的技能";
        }

        if (_cancelText != null)
            _cancelText.font = _runtimeFont;

        // 清理旧槽位
        for (int i = _slotContainer.childCount - 1; i >= 0; i--)
            Destroy(_slotContainer.GetChild(i).gameObject);

        // 动态生成技能槽
        for (int i = 0; i < enemySkills.Count; i++)
        {
            int captured = i;
            SkillInstance enemySkill = enemySkills[i];

            SkillSlotView slotView = Instantiate(_slotPrefab, _slotContainer);

            SkillViewData viewData = BuildSlotData(enemySkill);
            slotView.Refresh(viewData);

            // 点击 = 选择该技能
            Button slotBtn = slotView.GetComponent<Button>();
            if (slotBtn == null) slotBtn = slotView.gameObject.AddComponent<Button>();
            slotBtn.onClick.RemoveAllListeners();
            slotBtn.onClick.AddListener(() => OnSkillSelected(captured));
        }

        if (_cancelButton != null)
        {
            _cancelButton.onClick.RemoveAllListeners();
            _cancelButton.onClick.AddListener(ClosePopup);
        }

        if (_backdrop != null)
            _backdrop.SetActive(true);
        _popupPanel.SetActive(true);
    }

    private SkillViewData BuildSlotData(SkillInstance skill)
    {
        SkillViewData data = default;
        if (skill == null || skill.Data == null) return data;

        SkillData def = skill.Data;
        data.Icon = def.icon;
        data.Level = skill.Level;
        data.MaxLevel = skill.MaxLevel;
        data.IsEquipped = true;
        data.IsUnlocked = true;
        data.IsCoolingDown = false;
        data.ShowKeyLabel = false;  // 弹窗中隐藏键位标签

        bool hasSkill = PlayerHasSkill(def.skillId, out int playerLv, out _);
        if (hasSkill)
            data.KeyLabel = playerLv < skill.MaxLevel ? "升级" : "已满";
        else
            data.KeyLabel = HasEmptySlot() ? "新技能" : "无空槽";

        return data;
    }

    private bool HasEmptySlot()
    {
        for (int i = 0; i < _playerSkillManager.SlotCount; i++)
            if (_playerSkillManager.IsSlotUnlocked(i) && _playerSkillManager.GetSkill(i) == null)
                return true;
        return false;
    }

    private bool PlayerHasSkill(string skillId, out int level, out int slotIdx)
    {
        for (int i = 0; i < _playerSkillManager.SlotCount; i++)
        {
            SkillInstance skill = _playerSkillManager.GetSkill(i);
            if (skill != null && skill.Data.skillId == skillId)
            {
                level = skill.Level;
                slotIdx = i;
                return true;
            }
        }
        level = 0;
        slotIdx = -1;
        return false;
    }

    private void OnSkillSelected(int index)
    {
        if (index < 0 || index >= _enemySkills.Count) return;

        SkillInstance enemySkill = _enemySkills[index];
        string skillId = enemySkill.Data.skillId;

        if (PlayerHasSkill(skillId, out int playerLv, out int slotIdx))
        {
            if (playerLv < enemySkill.MaxLevel)
                _playerSkillManager.UpgradeSkill(slotIdx);
        }
        else
        {
            _playerSkillManager.AcquireSkill(skillId);
        }

        ClosePopup();
    }

    public void ClosePopup()
    {
        if (!_isShowing) return;
        _isShowing = false;

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);

        _onClose?.Invoke();
        _onClose = null;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 侵蚀二选一弹窗：时停后显示"吞噬"和"同化"两个选项。
/// 吞噬 → 打开技能夺取弹窗（SkillStealPopupManager）
/// 同化 → 将敌人转化为随从
/// </summary>
public class ErodeChoicePopupManager : MonoBehaviour
{
    public static ErodeChoicePopupManager Instance { get; private set; }

    [Header("弹窗 UI（预制体中预设）")]
    [SerializeField] private GameObject _backdrop;
    [SerializeField] private GameObject _popupPanel;
    [SerializeField] private Text _titleText;
    [SerializeField] private Button _devourButton;
    [SerializeField] private Text _devourText;
    [SerializeField] private Button _assimilateButton;
    [SerializeField] private Text _assimilateText;
    [SerializeField] private Button _cancelButton;
    [SerializeField] private Text _cancelText;

    private Font _runtimeFont;

    // 状态
    private EnemyCore _targetEnemy;
    private IReadOnlyList<SkillInstance> _enemySkills;
    private PlayerSkillManager _playerSkillManager;
    private Action _onClose;
    private bool _isShowing;

    private void Awake()
    {
        if (Instance == null)
            Instance = this;
        else
            Destroy(gameObject);

        _runtimeFont = Font.CreateDynamicFontFromOSFont("Arial", 16);

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    private void OnDestroy()
    {
        if (Instance == this)
            Instance = null;
    }

    /// <summary>
    /// 显示二选一弹窗。
    /// </summary>
    /// <param name="enemy">被命中的敌人</param>
    /// <param name="hasSkills">敌人是否有技能（无技能时吞噬按钮禁用）</param>
    /// <param name="enemySkills">敌人技能列表</param>
    /// <param name="player">玩家技能管理器</param>
    /// <param name="onClose">关闭回调</param>
    public void ShowPopup(EnemyCore enemy, bool hasSkills, IReadOnlyList<SkillInstance> enemySkills,
        PlayerSkillManager player, Action onClose)
    {
        if (_isShowing) return;
        _isShowing = true;

        _targetEnemy = enemy;
        _enemySkills = enemySkills;
        _playerSkillManager = player;
        _onClose = onClose;

        if (_popupPanel == null) { _isShowing = false; return; }

        // 标题
        if (_titleText != null)
        {
            _titleText.font = _runtimeFont;
            _titleText.text = "选择行动";
        }

        // 吞噬按钮
        if (_devourButton != null)
        {
            _devourButton.onClick.RemoveAllListeners();
            _devourButton.onClick.AddListener(OnDevour);
            _devourButton.interactable = hasSkills;
        }
        if (_devourText != null)
        {
            _devourText.font = _runtimeFont;
            _devourText.text = hasSkills ? "吞噬" : "吞噬（无技能）";
        }

        // 同化按钮
        if (_assimilateButton != null)
        {
            _assimilateButton.onClick.RemoveAllListeners();
            _assimilateButton.onClick.AddListener(OnAssimilate);
            _assimilateButton.interactable = !_targetEnemy.IsDead;
        }
        if (_assimilateText != null)
        {
            _assimilateText.font = _runtimeFont;
            _assimilateText.text = "同化";
        }

        // 取消按钮
        if (_cancelButton != null)
        {
            _cancelButton.onClick.RemoveAllListeners();
            _cancelButton.onClick.AddListener(ClosePopup);
        }
        if (_cancelText != null)
            _cancelText.font = _runtimeFont;

        // 显示
        if (_backdrop != null)
            _backdrop.SetActive(true);
        _popupPanel.SetActive(true);
    }

    private void OnDevour()
    {
        HideUI();

        SkillStealPopupManager popup = SkillStealPopupManager.Instance;
        if (popup != null && _enemySkills != null && _enemySkills.Count > 0)
        {
            popup.ShowPopup(_enemySkills, _playerSkillManager, () =>
            {
                // 技能夺取弹窗关闭 → 恢复时间
                _onClose?.Invoke();
                _onClose = null;
                _isShowing = false;
            });
        }
        else
        {
            // 无弹窗或无技能 → 直接关闭
            _onClose?.Invoke();
            _onClose = null;
            _isShowing = false;
        }
    }

    private void OnAssimilate()
    {
        HideUI();

        if (_targetEnemy != null && !_targetEnemy.IsDead && _playerSkillManager != null)
        {
            _targetEnemy.Assimilate(_playerSkillManager.CasterTransform);
        }

        _onClose?.Invoke();
        _onClose = null;
        _isShowing = false;
    }

    private void HideUI()
    {
        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    public void ClosePopup()
    {
        if (!_isShowing) return;
        _isShowing = false;

        HideUI();

        _onClose?.Invoke();
        _onClose = null;
    }
}

