/// <summary>
/// 侵蚀投射物命中逻辑 — 命中敌人后弹出二选一弹窗（吞噬 / 同化）。
/// 飞行由 Projectile 组件（ProjectileSkillEffect 自动添加）负责。
/// 挂载在 ErodeProjectile 预制体上，与 Projectile 组件共存。
/// </summary>
public class ErodeProjectile : MonoBehaviour
{
    private void OnTriggerEnter2D(Collider2D other)
    {
        // 只命中敌人
        if (!other.CompareTag("Enemy")) return;

        IEnemy enemy = other.GetComponent<IEnemy>();
        if (enemy == null) return;

        // 获取玩家技能管理器
        PlayerSkillManager player = FindPlayerSkillManager();
        if (player == null) return;

        var enemySkills = enemy.SkillInstances;
        bool hasSkills = enemySkills != null && enemySkills.Count > 0;

        // 暂停 + 弹窗
        Time.timeScale = 0f;

        EnemyCore core = enemy as EnemyCore;
        ErodeChoicePopupManager popup = ErodeChoicePopupManager.Instance;
        if (popup != null && core != null)
        {
            popup.ShowPopup(core, hasSkills, enemySkills, player, () => Time.timeScale = 1f);
        }
        else
        {
            Time.timeScale = 1f;
        }
    }

    private static PlayerSkillManager FindPlayerSkillManager()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<PlayerSkillManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        // 订阅房间切换事件——每次 OnEnable 都重新订阅，确保 SetParent 导致的
        // OnDisable→OnEnable 周期后仍然能响应后续房间切换。
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 敌人生存组件，负责血量管理并通过委托广播变化。
/// 实现 IDamageable 以便外部统一调用。
///
/// 数据源：MaxHealth 由 EnemyCore（或外部）在 Awake 后显式赋值，
///         然后调用 Initialize() 完成初始化。不在 Awake 中自动初始化。
/// </summary>
public class EnemyHealth : MonoBehaviour, IDamageable
{
    [Header("生命")]
    [Tooltip("由 EnemyCore 根据 EnemyConfig 赋值，也可独立设置")]
    public float MaxHealth = 30f;

    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;

    /// <summary>
    /// 由 EnemyCore 在设置 MaxHealth 后调用。
    /// 确保 _health 从最终 MaxHealth 初始化，避免数据源不一致。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;

        _health = MaxHealth;
        _initialized = true;
    }

    private void Awake()
    {
        // 不再自动初始化，由调用方（EnemyCore）控制初始化时机
    }

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
        {
            Die();
        }
    }

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>
    /// 清除 OnDied 事件的所有订阅者（用于同化时切换死亡处理逻辑）。
    /// </summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }
}

using UnityEngine;

/// <summary>
/// 移动组件：封装 Rigidbody2D 操作与视线检测缓存。
///
/// 速度数据源： EnemyConfig.patrolSpeed / EnemyConfig.chaseSpeed
///             由状态机在 Enter 时写入 MoveSpeed，组件本身不做初始化。
/// </summary>
[RequireComponent(typeof(Rigidbody2D))]
public class EnemyMovement : MonoBehaviour
{
    /// <summary>运行时当前速度（由状态机从 EnemyConfig 赋值，不在 Inspector 设置）</summary>
    [HideInInspector]
    public float MoveSpeed = 2f;

    private Rigidbody2D _rb;
    private float _sightCheckInterval = 0.2f;
    private float _nextSightCheckTime;
    private bool _cachedHasLineOfSight;
    private bool _wasInDetectionRange = false;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (_rb != null) _rb.freezeRotation = true;
    }

    public void Stop()
    {
        if (_rb != null) _rb.velocity = Vector2.zero;
    }

    public void MoveTowardsPosition(Vector2 target, float speedMultiplier = 1f)
    {
        if (_rb == null) return;
        Vector2 dir = (target - (Vector2)transform.position).normalized;
        _rb.velocity = dir * MoveSpeed * speedMultiplier;
    }

    public void SetVelocity(Vector2 vel)
    {
        if (_rb == null) return;
        _rb.velocity = vel;
    }

    /// <summary>直接传送到目标位置（通过 Rigidbody2D.position）</summary>
    public void Teleport(Vector2 targetPos)
    {
        if (_rb != null)
        {
            _rb.velocity = Vector2.zero;
            _rb.position = targetPos;
        }
        else
        {
            transform.position = targetPos;
        }
    }

    /// <summary>
    /// 带缓存的视线检测。调用时会基于 interval 减少 Linecast 次数。
    /// </summary>
    public bool HasLineOfSight(Vector2 targetPosition, float detectionRange, float sightCheckInterval = 0.2f)
    {
        float sqrDistance = ((Vector2)transform.position - targetPosition).sqrMagnitude;
        bool inRange = sqrDistance <= detectionRange * detectionRange;

        if (!inRange)
        {
            _wasInDetectionRange = false;
            _cachedHasLineOfSight = false;
            return false;
        }

        if (!_wasInDetectionRange)
        {
            _nextSightCheckTime = 0f; // force immediate check
            _wasInDetectionRange = true;
        }

        if (Time.time >= _nextSightCheckTime)
        {
            _nextSightCheckTime = Time.time + sightCheckInterval;
            RaycastHit2D hit = Physics2D.Linecast(transform.position, targetPosition);
            _cachedHasLineOfSight = hit.collider == null || !hit.collider.CompareTag("Wall");
        }

        return _cachedHasLineOfSight;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人的技能管理组件：负责装配技能、驱动冷却并提供 TryCast 接口。
/// </summary>
public class EnemySkillManager : MonoBehaviour
{
    private List<SkillInstance> _skillInstances = new List<SkillInstance>();

    public IReadOnlyList<SkillInstance> SkillInstances => _skillInstances;

    public void InitializeFromLibrary(SkillLibrary library, int randomMin = 1, int randomMax = 2)
    {
        _skillInstances.Clear();
        if (library == null) return;

        var datas = library.GetRandomDistinct(Random.Range(randomMin, randomMax + 1));
        foreach (var d in datas)
        {
            if (d == null) continue;
            var inst = library.CreateSkillInstance(d.skillId);
            if (inst != null) _skillInstances.Add(inst);
        }
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        foreach (var s in _skillInstances)
            s.TickCooldown(dt);
    }

    public bool TryCastSkill(int index, ISkillCaster caster, Vector2 dir)
    {
        if (index < 0 || index >= _skillInstances.Count) return false;
        return _skillInstances[index].TryCast(caster, dir);
    }
}

