using UnityEngine;

/// <summary>
/// 鍐插埡鎶€鑳芥晥鏋滐細鏂芥硶鑰呭悜鐩爣鏂瑰悜鐬Щ涓€娈佃窛绂汇€?
/// 鍙抽敭 -> Create -> Game -> Skill Effect -> Dash
