    [Header("鍐插埡閰嶇疆")]
    [Tooltip("鍐插埡璺濈")]
    public float distance = 5f;

    [Tooltip("鍐插埡鏃堕棿锛堢锛夛紝0 = 鐬棿锛?)]
    public float duration = 0.15f;

    [Tooltip("鍐插埡杩囩▼涓槸鍚︽棤鏁?)]
    public bool invincibleDuringDash = true;

    [Tooltip("鍐插埡鎷栧奖鐗规晥棰勫埗浣擄紙鍙€夛級")]
